    "statement": "Cidadã brasileira nata adquire voluntariamente a nacionalidade norte-americana por naturalização para facilitar seu trabalho nos Estados Unidos, sem fazer qualquer pedido expresso de renúncia à nacionalidade brasileira perante autoridade competente.",
