    "statement": "País membro da OMC reduz unilateralmente a tarifa de importação de automóveis oriundos de um país amigo sem integrá-lo em área de livre comércio ou união aduaneira, mantendo tarifa tripla para automóveis idênticos dos demais membros da OMC.",
